pub fn is_anagram(a: &str, b: &str) -> bool {
    let mut count = [0; 26]; // 26 letters in the English alphabet
    for c in a.chars().to_lowercase().chars() {
        count[(c - 'a') as usize] += 1;
    }
    for c in b.chars().to_lowercase().chars() {
        count[(c - 'a') as usize] -= 1;
        if count[(c - 'a') as usize] < 0 {
            return false;
        }
    }
    true
}

