    let left = 0;
    let right = v.len() - 1;
    while left <= right {
        let mid = left + (right - left) / 2;
        if v[mid] < target {
            left = mid + 1;
        } else if v[mid] > target {
            right = mid - 1;
        } else {
            return Some(mid);
        }
    }
    None
}

