pub fn median(v: &[f64]) -> Option<f64> {
    let mut left = v;
    let mut right = v;
    let mid = left.len() / 2;
    while left.len() > 1 {
        let middle = left.len() / 2;
        if left[middle].is_nan() {
            left = right;
            right = left.to_vec();
        } else {
            left = left.split_at(middle).1;
            right = right.split_at(middle).0;
        }
    }
    if left.len() == 0 {
        return right.last().copied();
    }
    let mid = right.len() / 2;
    if left[mid].is_nan() {
        left = right;
        right = left.to_vec();
    }
    let a = left[mid];
    let b = right[mid];
    if a.is_nan() || b.is_nan() {
        return a;
    }
    if a < b {
        left = &left[mid..];
    } else {
        right = &right[..mid];
    }
    Some((a + b) / 2.0)
}

