    if k == 0 {
        return v.to_vec();
    }
    let length = v.len();
    let effective_k = k % length;
    if effective_k == 0 {
        return v.to_vec();
    }
    let (left, right) = v.split_at(effective_k);
    right.into_iter().chain(left.iter()).collect()
}

